INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (1, 'おはようございます。', 'おはようございます。', '좋은 아침입니다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (2, '今日は天気がいいですね。', 'きょうはてんきがいいですね。', '오늘은 날씨가 좋네요.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (3, 'これは私の本です。', 'これはわたしのほんです。', '이것은 제 책입니다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (4, 'すみません、駅はどこですか。', 'すみません、えきはどこですか。', '실례합니다, 역은 어디예요?', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (5, '私は毎朝お茶を飲みます。', 'わたしはまいあさおちゃをのみます。', '저는 매일 아침 차를 마셔요.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (6, '明日は友達と映画を見ます。', 'あしたはともだちとえいがをみます。', '내일은 친구와 영화를 봐요.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (7, '昨日は雨が降りました。', 'きのうはあめがふりました。', '어제는 비가 내렸어요.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (8, '今からご飯を食べます。', 'いまからごはんをたべます。', '지금부터 밥을 먹을게요.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (9, '週末は家でゆっくり休みます。', 'しゅうまつはいえでゆっくりやすみます。', '주말은 집에서 느긋하게 쉬어요.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (10, '夜遅くまで勉強しました。', 'よるおそくまでべんきょうしました。', '밤 늦게까지 공부했어요.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (11, 'もう少し大きい声で話してください。', 'もうすこしおおきいこえではなしてください。', '조금 더 큰 목소리로 말해주세요.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (12, '今度の休みに旅行に行きたいです。', 'こんどのやすみにりょこうにいきたいです。', '이번 휴가에 여행을 가고 싶어요.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (13, '電車が遅れて会議に遅刻しました。', 'でんしゃがおくれてかいぎにちこくしました。', '전철이 늦어서 회의에 지각했어요.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (14, '難しい問題でしたが、最後まで頑張りました。', 'むずかしいもんだいでしたが、さいごまでがんばりました。', '어려운 문제였지만 끝까지 열심히 했어요.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (15, 'この道をまっすぐ行くと図書館があります。', 'このみちをまっすぐいくととしょかんがあります。', '이 길을 곧장 가면 도서관이 있어요.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (16, '忙しくても毎日運動するようにしています。', 'いそがしくてもまいにちうんどうするようにしています。', '바쁘더라도 매일 운동하도록 하고 있어요.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (17, '約束の時間に間に合わなくて困りました。', 'やくそくのじかんにまにあわなくてこまりました。', '약속 시간에 맞추지 못해서 곤란했어요.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (18, '先生に分からないところを聞きました。', 'せんせいにわからないところをききました。', '선생님께 모르는 부분을 물었어요.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (19, '引っ越しの準備で毎日忙しいです。', 'ひっこしのじゅんびでまいにちいそがしいです。', '이사 준비로 매일 바빠요.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (20, '天気予報によると、明日は雪が降るそうです。', 'てんきよほうによると、あしたはゆきがふるそうです。', '일기예보에 따르면 내일은 눈이 온다고 해요.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (21, '経済の状況が悪くなっているため、就職が難しくなっている。', 'けいざいのじょうきょうがわるくなっているため、しゅうしょくがむずかしくなっている。', '경제 상황이 나빠지고 있어서 취업이 어려워지고 있다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (22, '彼は失敗を繰り返しながらも諦めずに挑戦を続けた。', 'かれはしっぱいをくりかえしながらもあきらめずにちょうせんをつづけた。', '그는 실패를 반복하면서도 포기하지 않고 도전을 계속했다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (23, '環境を守るために、私たちにできることは何でしょうか。', 'かんきょうをまもるために、わたしたちにできることはなんでしょうか。', '환경을 지키기 위해 우리가 할 수 있는 일은 무엇일까요.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (24, '一度決めたことは最後まで責任を持ってやり遂げたい。', 'いちどきめたことはさいごまでせきにんをもってやりとげたい。', '한번 정한 일은 끝까지 책임을 지고 해내고 싶다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (25, '忙しい日々の中でも、家族との時間を大切にしている。', 'いそがしいひびのなかでも、かぞくとのじかんをたいせつにしている。', '바쁜 나날 속에서도 가족과의 시간을 소중히 하고 있다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (26, '名前は何ですか。', 'なまえはなんですか。', '이름이 무엇인가요?', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (27, '誕生日はいつですか。', 'たんじょうびはいつですか。', '생일이 언제예요?', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (28, 'この漢字はどう読みますか。', 'このかんじはどうよみますか。', '이 한자는 어떻게 읽나요?', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (29, '頭が痛いので、今日は早く帰ります。', 'あたまがいたいので、きょうははやくかえります。', '머리가 아파서 오늘은 일찍 돌아가요.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (30, '相手の立場になって考えることが大切だと思う。', 'あいてのたちばになってかんがえることがたいせつだとおもう。', '상대방의 입장이 되어 생각하는 것이 중요하다고 생각한다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (31, '努力すれば必ず結果が出るとは限らない。', 'どりょくすればかならずけっかがでるとはかぎらない。', '노력하면 반드시 결과가 나온다고는 할 수 없다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (32, '今日はとても楽しい一日でした。', 'きょうはとてもたのしいいちにちでした。', '오늘은 매우 즐거운 하루였어요.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (33, '締め切りが近いにもかかわらず、まだ半分も終わっていない。', 'しめきりがちかいにもかかわらず、まだはんぶんもおわっていない。', '마감이 얼마 안 남았는데도 아직 절반도 끝나지 않았다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (34, '一度失敗したくらいで諦めるわけにはいかない。', 'いちどしっぱいしたくらいであきらめるわけにはいかない。', '한 번 실패한 정도로 포기할 수는 없다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (35, '雨が降りそうなので、傘を持って行くことにした。', 'あめがふりそうなので、かさをもっていくことにした。', '비가 올 것 같아서 우산을 가지고 가기로 했다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (36, '彼はお金があるくせに、いつも安いものしか買わない。', 'かれはおかねがあるくせに、いつもやすいものしかかわない。', '그는 돈이 있으면서도 항상 싼 것만 산다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (37, '説明を聞いたとたん、みんなが一斉に驚いた顔をした。', 'せつめいをきいたとたん、みんながいっせいにおどろいたかおをした。', '설명을 듣자마자 모두가 일제히 놀란 표정을 지었다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (38, '彼の助けのおかげで、無事に仕事を終えることができた。', 'かれのたすけのおかげで、むじにしごとをおえることができた。', '그의 도움 덕분에 무사히 일을 끝낼 수 있었다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (39, '忙しさのせいで、最近運動する時間がまったく取れない。', 'いそがしさのせいで、さいきんうんどうするじかんがまったくとれない。', '바쁜 탓에 요즘 운동할 시간이 전혀 나지 않는다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (40, '彼女にとって、家族と過ごす時間が一番大切なものだ。', 'かのじょにとって、かぞくとすごすじかんがいちばんたいせつなものだ。', '그녀에게 있어 가족과 보내는 시간이 가장 중요한 것이다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (41, '練習を積んだ結果、以前より上手に話せるようになった。', 'れんしゅうをつんだけっか、いぜんよりじょうずにはなせるようになった。', '연습을 쌓은 결과 이전보다 능숙하게 말할 수 있게 되었다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (42, '彼はまだ若いくせに、経験豊かな人のように話す。', 'かれはまだわかいくせに、けいけんゆたかなひとのようにはなす。', '그는 아직 젊으면서도 경험이 풍부한 사람처럼 말한다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (43, 'お金が足りないというより、時間が足りないのが問題だ。', 'おかねがたりないというより、じかんがたりないのがもんだいだ。', '돈이 부족하다기보다 시간이 부족한 것이 문제다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (44, '彼が来ないなら、会議を始めるしかないだろう。', 'かれがこないなら、かいぎをはじめるしかないだろう。', '그가 오지 않으면 회의를 시작할 수밖에 없을 것이다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (45, '実力があるだけに、もう少し自信を持ってもいいと思う。', 'じつりょくがあるだけに、もうすこしじしんをもってもいいとおもう。', '실력이 있는 만큼 조금 더 자신감을 가져도 될 것 같다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (46, '事故の話を聞いて、思わず心配になった。', 'じこのはなしをきいて、おもわずしんぱいになった。', '사고 이야기를 듣고 나도 모르게 걱정이 되었다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (47, '天気さえよければ、遠足は予定どおり行われるはずだ。', 'てんきさえよければ、えんそくはよていどおりおこなわれるはずだ。', '날씨만 좋으면 소풍은 예정대로 진행될 것이다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (48, '彼の実力は誰もが認めるところであり、疑う余地はない。', 'かれのじつりょくはだれもがみとめるところであり、うたがうよちはない。', '그의 실력은 누구나 인정하는 바이며 의심할 여지가 없다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (49, '経験の浅い彼にこの仕事を任せるのは無理があるだろう。', 'けいけんのあさいかれにこのしごとをまかせるのはむりがあるだろう。', '경험이 부족한 그에게 이 일을 맡기는 것은 무리가 있을 것이다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (50, '努力もせずに結果だけを求めるのは虫がよすぎる。', 'どりょくもせずにけっかだけをもとめるのはむしがよすぎる。', '노력도 하지 않고 결과만 바라는 것은 지나치게 이기적이다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (51, 'あの人は口では簡単だと言うものの、実際はそう簡単ではない。', 'あのひとはくちではかんたんだというものの、じっさいはそうかんたんではない。', '그 사람은 말로는 쉽다고 하지만 실제로는 그렇게 쉽지 않다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (52, '規則とはいえ、状況によっては例外を認めるべきだ。', 'きそくとはいえ、じょうきょうによってはれいがいをみとめるべきだ。', '규칙이라고는 해도 상황에 따라서는 예외를 인정해야 한다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (53, '彼女は仕事一筋で、休みの日でさえ仕事のことを考えている。', 'かのじょはしごといっすじで、やすみのひでさえしごとのことをかんがえている。', '그녀는 일에만 몰두해서 쉬는 날에도 일 생각만 한다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (54, '収入が減ったからといって、生活の質を落としたくはない。', 'しゅうにゅうがへったからといって、せいかつのしつをおとしたくはない。', '수입이 줄었다고 해서 생활의 질을 낮추고 싶지는 않다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (55, 'あの店の料理は評判にたがわず、本当においしかった。', 'あのみせのりょうりはひょうばんにたがわず、ほんとうにおいしかった。', '그 가게 요리는 평판대로 정말 맛있었다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (56, '一度決めたことを最後まで守るのが彼のやり方だ。', 'いちどきめたことをさいごまでまもるのがかれのやりかただ。', '한번 정한 것을 끝까지 지키는 것이 그의 방식이다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (57, 'あの映画は感動的だと聞いていたが、実際に見てもその通りだった。', 'あのえいがはかんどうてきだときいていたが、じっさいにみてもそのとおりだった。', '그 영화는 감동적이라고 들었는데 실제로 봐도 그대로였다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (58, '都会での生活に慣れてしまうと、田舎の静けさが恋しくなる。', 'とかいでのせいかつになれてしまうと、いなかのしずけさがこいしくなる。', '도시 생활에 익숙해지면 시골의 조용함이 그리워진다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (59, '面倒だと分かっていながら、つい後回しにしてしまう。', 'めんどうだとわかっていながら、ついあとまわしにしてしまう。', '귀찮다는 것을 알면서도 자꾸 미루게 된다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (60, '誰にでも失敗はあるものだから、あまり自分を責めないほうがいい。', 'だれにでもしっぱいはあるものだから、あまりじぶんをせめないほうがいい。', '누구에게나 실패는 있는 법이니 너무 자신을 탓하지 않는 게 좋다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (61, '状況を踏まえて、今後の対応を決めなければならない。', 'じょうきょうをふまえて、こんごのたいおうをきめなければならない。', '상황을 감안해서 앞으로의 대응을 결정해야 한다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (62, '彼の意見はもちろん、他の人の意見も聞いてから決めよう。', 'かれのいけんはもちろん、ほかのひとのいけんもきいてからきめよう。', '그의 의견은 물론 다른 사람의 의견도 들은 후에 결정하자.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (63, '明日は早く起きなければならない。', 'あすははやくおきなければならない。', '내일은 일찍 일어나야 한다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (64, '毎晩お風呂に入ってから寝ます。', 'まいばんおふろにはいってからねます。', '매일 밤 목욕을 하고 나서 잔다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (65, '冬になると、外がとても寒くなります。', 'ふゆになると、そとがとてもさむくなります。', '겨울이 되면 밖이 매우 추워진다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (66, '母は毎日お弁当を作ってくれます。', 'はははまいにちおべんとうをつくってくれます。', '어머니는 매일 도시락을 만들어 주신다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (67, '週に三回体を動かすようにしています。', 'しゅうにさんかいたいをうごかすようにしています。', '일주일에 세 번 몸을 움직이도록 하고 있다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (68, '駅から家まで歩いて十五分くらいです。', 'えきからいえまであるいてじゅうごふんくらいです。', '역에서 집까지 걸어서 15분 정도다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (69, 'この本はとても面白くて、一日で読み終えました。', 'このほんはとてもおもしろくて、いちにちでよみおえました。', '이 책은 정말 재미있어서 하루 만에 다 읽었다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (70, '今度の休みに家族と海に行く予定です。', 'こんどのやすみにかぞくとうみにいくよていです。', '이번 휴가에 가족과 바다에 갈 예정이다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (71, '冷蔵庫に牛乳がもうありません。', 'れいぞうこにぎゅうにゅうがもうありません。', '냉장고에 우유가 더 이상 없다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (72, '友達の誕生日に贈り物を買いました。', 'ともだちのたんじょうびにおくりものをかいました。', '친구 생일에 선물을 샀다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (73, '毎朝六時に起きて、散歩をします。', 'まいあさろくじにおきて、さんぽをします。', '매일 아침 6시에 일어나서 산책을 한다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (74, '今日の晩ご飯は魚と野菜にしましょう。', 'きょうのばんごはんはさかなとやさいにしましょう。', '오늘 저녁은 생선과 채소로 합시다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (75, '大きい荷物があるので、車で行きます。', 'おおきいにもつがあるので、くるまでいきます。', '큰 짐이 있어서 차로 갑니다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (76, '兄は東京の大学に通っています。', 'あにはとうきょうのだいがくにかよっています。', '형은 도쿄의 대학에 다니고 있다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (77, '授業が終わったら、図書館で勉強します。', 'じゅぎょうがおわったら、としょかんでべんきょうします。', '수업이 끝나면 도서관에서 공부합니다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (78, '玄関の前に自転車が三台止まっています。', 'げんかんのまえにじてんしゃがさんだいとまっています。', '현관 앞에 자전거가 세 대 서 있다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (79, '弟はまだ小学生ですが、料理が得意です。', 'おとうとはまだしょうがくせいですが、りょうりがとくいです。', '남동생은 아직 초등학생이지만 요리를 잘한다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (80, '昨日の夜、久しぶりに友達と電話で話しました。', 'きのうのよる、ひさしぶりにともだちとでんわではなしました。', '어제 밤 오랜만에 친구와 전화로 이야기했다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (81, 'この部屋は駅にとても近くて便利です。', 'このへやはえきにとてもちかくてべんりです。', '이 방은 역에서 매우 가까워서 편리하다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (82, '妹は毎日日記を書いています。', 'いもうとはまいにちにっきをかいています。', '여동생은 매일 일기를 쓰고 있다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (83, '今朝は電車が混んでいて大変でした。', 'けさはでんしゃがこんでいてたいへんでした。', '오늘 아침은 전철이 혼잡해서 힘들었다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (84, '日曜日はいつも家族と一緒に過ごします。', 'にちようびはいつもかぞくといっしょにすごします。', '일요일은 항상 가족과 함께 보낸다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (85, 'このお店の料理はいつもおいしいです。', 'このおみせのりょうりはいつもおいしいです。', '이 가게 요리는 항상 맛있다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (86, '子供の頃、よくこの公園で遊びました。', 'こどものころ、よくこのこうえんであそびました。', '어릴 때 자주 이 공원에서 놀았다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (87, '来週から新しい仕事が始まります。', 'らいしゅうからあたらしいしごとがはじまります。', '다음 주부터 새 일이 시작된다.', 'N5', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (88, '天気が悪くなりそうなので、早めに出発しましょう。', 'てんきがわるくなりそうなので、はやめにしゅっぱつしましょう。', '날씨가 나빠질 것 같으니 일찍 출발합시다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (89, '彼は仕事が終わってから、いつも走りに行きます。', 'かれはしごとがおわってから、いつもはしりにいきます。', '그는 일이 끝난 후 항상 뛰러 간다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (90, '会議の前に資料を準備しておいてください。', 'かいぎのまえにしりょうをじゅんびしておいてください。', '회의 전에 자료를 준비해 두세요.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (91, 'この電話は去年買ったばかりなのに、もう壊れてしまった。', 'このでんわはきょねんかったばかりなのに、もうこわれてしまった。', '이 전화는 작년에 산 지 얼마 안 됐는데 벌써 고장 나 버렸다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (92, '説明書を読んでも、使い方がよく分からない。', 'せつめいしょをよんでも、つかいかたがよくわからない。', '설명서를 읽어도 사용법을 잘 모르겠다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (93, '頑張って勉強したので、試験に合格できた。', 'がんばってべんきょうしたので、しけんにごうかくできた。', '열심히 공부해서 시험에 합격할 수 있었다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (94, '荷物が重すぎて、一人では運べない。', 'にもつがおもすぎて、ひとりでははこべない。', '짐이 너무 무거워서 혼자서는 옮길 수 없다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (95, '彼女は日本語だけでなく、英語も上手に話せる。', 'かのじょはにほんごだけでなく、えいごもじょうずにはなせる。', '그녀는 일본어뿐만 아니라 영어도 잘 말할 수 있다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (96, '台風のせいで、電車が全部止まってしまった。', 'たいふうのせいで、でんしゃがぜんぶとまってしまった。', '태풍 때문에 전철이 전부 멈춰 버렸다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (97, '予約をしていなかったので、その店に入れなかった。', 'よやくをしていなかったので、そのみせにいれなかった。', '예약을 하지 않아서 그 가게에 들어갈 수 없었다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (98, '引っ越したばかりで、まだ荷物が片付いていない。', 'ひっこしたばかりで、まだにもつがかたづいていない。', '이사한 지 얼마 안 돼서 아직 짐이 정리되지 않았다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (99, '彼はお酒を飲むと、いつも歌いたくなるらしい。', 'かれはおさけをのむと、いつもうたいたくなるらしい。', '그는 술을 마시면 항상 노래하고 싶어지는 것 같다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (100, '電気をつけたまま、寝てしまったようだ。', 'でんきをつけたまま、ねてしまったようだ。', '불을 켠 채로 자 버린 것 같다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (101, 'この道具は使い方が簡単で、誰でも使える。', 'このどうぐはつかいかたがかんたんで、だれでもつかえる。', '이 도구는 사용법이 간단해서 누구나 쓸 수 있다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (102, '彼に頼まれた仕事を、忘れずに終わらせないといけない。', 'かれにたのまれたしごとを、わすれずにおわらせないといけない。', '그가 부탁한 일을 잊지 말고 끝내야 한다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (103, 'お客様に失礼のないよう、丁寧に対応してください。', 'おきゃくさまにしつれいのないよう、ていねいにたいおうしてください。', '손님에게 실례가 되지 않도록 정중하게 대응해 주세요.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (104, '今日中にこの書類を提出しなければならない。', 'きょうじゅうにこのしょるいをていしゅつしなければならない。', '오늘 중으로 이 서류를 제출해야 한다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (105, '熱があるみたいなので、病院に行ったほうがいい。', 'ねつがあるみたいなので、びょういんにいったほうがいい。', '열이 있는 것 같으니 병원에 가는 게 좋겠다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (106, '大事な会議があるから、絶対に遅れてはいけない。', 'だいじなかいぎがあるから、ぜったいにおくれてはいけない。', '중요한 회의가 있으니 절대로 늦으면 안 된다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (107, '彼女はいつも周りの人を気にかけてくれる優しい人だ。', 'かのじょはいつもまわりのひとをきにかけてくれるやさしいひとだ。', '그녀는 항상 주변 사람을 신경 써 주는 착한 사람이다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (108, 'この問題について、もう一度話し合う必要がある。', 'このもんだいについて、もういちどはなしあうひつようがある。', '이 문제에 대해 다시 한번 논의할 필요가 있다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (109, '急に予定が変わって、旅行に行けなくなった。', 'きゅうによていがかわって、りょこうにいけなくなった。', '갑자기 일정이 바뀌어서 여행을 갈 수 없게 되었다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (110, 'どんなに頑張っても、結果がすぐには出ないものだ。', 'どんなにがんばっても、けっかがすぐにはでないものだ。', '아무리 노력해도 결과가 바로 나오지는 않는 법이다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (111, '彼は約束の時間より三十分も早く来ていた。', 'かれはやくそくのじかんよりさんじっぷんもはやくきていた。', '그는 약속 시간보다 30분이나 일찍 와 있었다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (112, '子供にはできるだけ自由に育ってほしいと思っている。', 'こどもにはできるだけじゆうにそだってほしいとおもっている。', '아이에게는 가능한 한 자유롭게 자라기를 바라고 있다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (113, 'お金を貯めて、いつか自分の店を持ちたい。', 'おかねをためて、いつかじぶんのみせをもちたい。', '돈을 모아서 언젠가 내 가게를 갖고 싶다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (114, '彼の話は長すぎて、最後まで聞くのが大変だった。', 'かれのはなしはながすぎて、さいごまできくのがたいへんだった。', '그의 이야기는 너무 길어서 끝까지 듣는 게 힘들었다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (115, '何度も練習したおかげで、上手に発表できた。', 'なんどもれんしゅうしたおかげで、じょうずにはっぴょうできた。', '여러 번 연습한 덕분에 능숙하게 발표할 수 있었다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (116, '会社を辞めて、自分の好きなことをやってみたい。', 'かいしゃをやめて、じぶんのすきなことをやってみたい。', '회사를 그만두고 내가 좋아하는 일을 해보고 싶다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (117, 'あまりに忙しくて、ご飯を食べる時間さえなかった。', 'あまりにいそがしくて、ごはんをたべるじかんさえなかった。', '너무 바빠서 밥 먹을 시간조차 없었다.', 'N4', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (118, '彼は忙しいと言っていたが、意外と時間があるようだ。', 'かれはいそがしいといっていたが、いがいとじかんがあるようだ。', '그는 바쁘다고 했지만 의외로 시간이 있는 것 같다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (119, '新しい環境に慣れるまでには、少し時間がかかるものだ。', 'あたらしいかんきょうになれるまでには、すこしじかんがかかるものだ。', '새로운 환경에 익숙해지기까지는 조금 시간이 걸리는 법이다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (120, '忙しい中、時間を作ってくれたことに感謝している。', 'いそがしいなか、じかんをつくってくれたことにかんしゃしている。', '바쁜 가운데 시간을 내준 것에 감사하고 있다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (121, '彼女の意見を聞くうちに、自分の考えが変わっていった。', 'かのじょのいけんをきくうちに、じぶんのかんがえがかわっていった。', '그녀의 의견을 듣는 사이에 내 생각이 바뀌어 갔다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (122, 'どれだけ準備しても、本番では何が起こるか分からない。', 'どれだけじゅんびしても、ほんばんではなにがおこるかわからない。', '아무리 준비해도 실전에서는 무슨 일이 일어날지 모른다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (123, '彼のやり方には賛成しかねる部分がある。', 'かれのやりかたにはさんせいしかねるぶぶんがある。', '그의 방식에는 찬성하기 어려운 부분이 있다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (124, '忙しさにかまけて、健康管理を怠っていた。', 'いそがしさにかまけて、けんこうかんりをおこたっていた。', '바쁨을 핑계로 건강 관리를 게을리 했었다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (125, 'あの人は口が悪いものの、根はとても優しい。', 'あのひとはくちがわるいものの、ねはとてもやさしい。', '그 사람은 말투가 나쁘지만 근본은 매우 착하다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (126, '予想に反して、今年の売り上げは大きく伸びた。', 'よそうにはんして、ことしのうりあげはおおきくのびた。', '예상과 달리 올해 매출은 크게 늘었다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (127, '状況が変わり次第、すぐに連絡します。', 'じょうきょうがかわりしだい、すぐにれんらくします。', '상황이 바뀌는 대로 즉시 연락하겠습니다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (128, '一生懸命努力したにもかかわらず、結果は思わしくなかった。', 'いっしょうけんめいどりょくしたにもかかわらず、けっかはおもわしくなかった。', '열심히 노력했음에도 결과는 좋지 않았다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (129, '彼女は忙しさを理由に、約束を何度も破っている。', 'かのじょはいそがしさをりゆうに、やくそくをなんどもやぶっている。', '그녀는 바쁘다는 이유로 약속을 여러 번 어기고 있다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (130, '相手の気持ちを考えずに発言するのはよくない。', 'あいてのきもちをかんがえずにはつげんするのはよくない。', '상대방의 마음을 생각하지 않고 발언하는 것은 좋지 않다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (131, 'あの映画を見て以来、彼の考え方が変わったようだ。', 'あのえいがをみていらい、かれのかんがえかたがかわったようだ。', '그 영화를 본 이후로 그의 사고방식이 바뀐 것 같다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (132, '忙しい時期を過ぎたら、少しゆっくりしたい。', 'いそがしいじきをすぎたら、すこしゆっくりしたい。', '바쁜 시기가 지나면 조금 느긋하게 지내고 싶다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (133, '彼は自分の間違いを認めようとしない。', 'かれはじぶんのまちがいをみとめようとしない。', '그는 자신의 실수를 인정하려 하지 않는다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (134, '話を聞けば聞くほど、彼の苦労がよく分かった。', 'はなしをきけばきくほど、かれのくろうがよくわかった。', '이야기를 들으면 들을수록 그의 고생이 잘 이해되었다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (135, 'どんなに苦しくても、途中で投げ出したくない。', 'どんなにくるしくても、とちゅうでなげだしたくない。', '아무리 힘들어도 중간에 포기하고 싶지 않다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (136, '彼は口約束だけで、実際には何もしてくれなかった。', 'かれはくちやくそくだけで、じっさいにはなにもしてくれなかった。', '그는 말로만 약속하고 실제로는 아무것도 해주지 않았다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (137, '経済が回復するにつれて、雇用も少しずつ増えてきた。', 'けいざいがかいふくするにつれて、こようもすこしずつふえてきた。', '경제가 회복됨에 따라 고용도 조금씩 늘어났다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (138, '今回の失敗を教訓に、次はもっと慎重に進めたい。', 'こんかいのしっぱいをきょうくんに、つぎはもっとしんちょうにすすめたい。', '이번 실패를 교훈으로 삼아 다음에는 더 신중하게 진행하고 싶다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (139, '彼女は表面上は元気そうに見えるが、実は悩んでいるらしい。', 'かのじょはひょうめんじょうはげんきそうにみえるが、じつはなやんでいるらしい。', '그녀는 겉으로는 밝아 보이지만 사실은 고민하고 있는 것 같다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (140, '何を言われても、彼は全く動じない様子だった。', 'なにをいわれても、かれはまったくどうじないようすだった。', '무슨 말을 들어도 그는 전혀 동요하지 않는 모습이었다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (141, '忘れないうちに、書き留めておいたほうがいい。', 'わすれないうちに、かきとめておいたほうがいい。', '잊기 전에 적어 두는 것이 좋다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (142, 'あの会社は業績が伸び悩んでいるらしい。', 'あのかいしゃはぎょうせきがのびなやんでいるらしい。', '그 회사는 실적이 부진한 것 같다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (143, '彼が黙っているのを見ると、何か隠しているのではないかと思う。', 'かれがだまっているのをみると、なにかかくしているのではないかとおもう。', '그가 침묵하고 있는 것을 보면 뭔가 숨기고 있는 게 아닐까 싶다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (144, '忙しくても、家族との時間だけは削らないようにしている。', 'いそがしくても、かぞくとのじかんだけはけずらないようにしている。', '바빠도 가족과의 시간만은 줄이지 않도록 하고 있다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (145, '一度信頼を失うと、それを取り戻すのは簡単ではない。', 'いちどしんらいをうしなうと、それをとりもどすのはかんたんではない。', '한번 신뢰를 잃으면 그것을 되찾는 것은 쉽지 않다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (146, '彼の説明はあいまいで、結局よく分からなかった。', 'かれのせつめいはあいまいで、けっきょくよくわからなかった。', '그의 설명은 모호해서 결국 잘 이해하지 못했다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (147, 'これは私一人の問題ではなく、みんなで考えるべきことだ。', 'これはわたしひとりのもんだいではなく、みんなでかんがえるべきことだ。', '이것은 나 혼자만의 문제가 아니라 다 함께 생각해야 할 일이다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (148, '彼女は仕事に対する姿勢が非常にまじめだ。', 'かのじょはしごとにたいするしせいがひじょうにまじめだ。', '그녀는 일에 대한 자세가 매우 진지하다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (149, '準備が足りなかったせいで、発表がうまくいかなかった。', 'じゅんびがたりなかったせいで、はっぴょうがうまくいかなかった。', '준비가 부족했던 탓에 발표가 잘되지 않았다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (150, '彼は忙しさにもかかわらず、いつも笑顔を見せる。', 'かれはいそがしさにもかかわらず、いつもえがおをみせる。', '그는 바쁨에도 불구하고 항상 웃는 얼굴을 보인다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (151, '話し合った結果、計画を少し変更することになった。', 'はなしあったけっか、けいかくをすこしへんこうすることになった。', '논의한 결과 계획을 조금 변경하게 되었다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (152, '彼はまるで何も知らないかのように振る舞っていた。', 'かれはまるでなにもしらないかのようにふるまっていた。', '그는 마치 아무것도 모르는 것처럼 행동하고 있었다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (153, '期待していただけに、結果を聞いてがっかりした。', 'きたいしていただけに、けっかをきいてがっかりした。', '기대했던 만큼 결과를 듣고 실망했다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (154, '彼女の言葉には、どこか信じられない部分があった。', 'かのじょのことばには、どこかしんじられないぶぶんがあった。', '그녀의 말에는 어딘가 믿기지 않는 부분이 있었다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (155, '会議の内容を踏まえて、次にすることを考えよう。', 'かいぎのないようをふまえて、つぎにすることをかんがえよう。', '회의 내용을 바탕으로 다음에 할 일을 생각해 보자.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (156, '状況が厳しいのは分かっているが、諦めたくはない。', 'じょうきょうがきびしいのはわかっているが、あきらめたくはない。', '상황이 어려운 것은 알지만 포기하고 싶지는 않다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (157, '彼は自分の失敗を他人のせいにする傾向がある。', 'かれはじぶんのしっぱいをたにんのせいにするけいこうがある。', '그는 자신의 실수를 남의 탓으로 돌리는 경향이 있다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (158, '忙しいながらも、彼は毎日運動を欠かさない。', 'いそがしいながらも、かれはまいにちうんどうをかかさない。', '바쁘면서도 그는 매일 운동을 거르지 않는다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (159, '説明を聞けば、それほど難しい話ではないと分かる。', 'せつめいをきけば、それほどむずかしいはなしではないとわかる。', '설명을 들으면 그다지 어려운 이야기가 아니라는 것을 알게 된다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (160, '忙しい時ほど、計画的に動く必要がある。', 'いそがしいときほど、けいかくてきにうごくひつようがある。', '바쁠 때일수록 계획적으로 움직일 필요가 있다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (161, '彼女は一度言ったことを絶対に曲げない性格だ。', 'かのじょはいちどいったことをぜったいにまげないせいかくだ。', '그녀는 한번 말한 것을 절대 굽히지 않는 성격이다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (162, '結果はともかく、最後まで頑張ったことに意味がある。', 'けっかはともかく、さいごまでがんばったことにいみがある。', '결과는 어찌 됐든 끝까지 노력한 것에 의미가 있다.', 'N3', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (163, '彼の言動には、どこか腑に落ちない点が多い。', 'かれのげんどうには、どこかふにおちないてんがおおい。', '그의 언행에는 어딘가 이해되지 않는 점이 많다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (164, '制度が整っているとはいえ、実際に活用されているとは限らない。', 'せいどがととのっているとはいえ、じっさいにかつようされているとはかぎらない。', '제도가 갖춰져 있다고는 해도 실제로 활용되고 있다고는 할 수 없다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (165, '彼は経験を積むにつれて、判断力も磨かれていった。', 'かれはけいけんをつむにつれて、はんだんりょくもみがかれていった。', '그는 경험을 쌓아가면서 판단력도 다듬어졌다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (166, '表面的な成功にとらわれず、本質を見極めることが大切だ。', 'ひょうめんてきなせいこうにとらわれず、ほんしつをみきわめることがたいせつだ。', '표면적인 성공에 얽매이지 않고 본질을 파악하는 것이 중요하다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (167, '一見簡単そうに見えるが、実際にやってみると難しい。', 'いっけんかんたんそうにみえるが、じっさいにやってみるとむずかしい。', '겉보기에는 쉬워 보이지만 실제로 해보면 어렵다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (168, '彼の発言は、時と場合によって受け取られ方が異なる。', 'かれのはつげんは、ときとばあいによってうけとられかたがことなる。', '그의 발언은 때와 상황에 따라 받아들여지는 방식이 다르다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (169, '状況が好転する見込みは、今のところ薄いようだ。', 'じょうきょうがこうてんするみこみは、いまのところうすいようだ。', '상황이 호전될 가능성은 지금으로서는 낮은 것 같다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (170, '彼女は他人の評価に一切左右されない強さを持っている。', 'かのじょはたにんのひょうかにいっさいさゆうされないつよさをもっている。', '그녀는 타인의 평가에 전혀 좌우되지 않는 강함을 가지고 있다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (171, '一時の感情に流されて判断すると、後で後悔することが多い。', 'いちじのかんじょうにながされてはんだんすると、あとでこうかいすることがおおい。', '순간의 감정에 휩쓸려 판단하면 나중에 후회하는 경우가 많다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (172, 'あの企業は業界内で高い評価を得ているようだ。', 'あのきぎょうはぎょうかいないでたかいひょうかをえているようだ。', '그 기업은 업계 내에서 높은 평가를 받고 있는 것 같다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (173, '彼はいかなる困難にも屈しない強い意志を持っている。', 'かれはいかなるこんなんにもくっしないつよいいしをもっている。', '그는 어떠한 어려움에도 굴하지 않는 강한 의지를 가지고 있다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (174, '今回の結果を受けて、方針を見直す必要が出てきた。', 'こんかいのけっかをうけて、ほうしんをみなおすひつようがでてきた。', '이번 결과를 받아들여 방침을 재검토할 필요가 생겼다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (175, '誰しも一度は失敗を経験するものだ。', 'だれしもいちどはしっぱいをけいけんするものだ。', '누구나 한번은 실패를 경험하는 법이다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (176, '世の中の変化に応じて、考え方を柔軟に変えていくべきだ。', 'よのなかのへんかにおうじて、かんがえかたをじゅうなんにかえていくべきだ。', '세상의 변화에 맞춰 사고방식을 유연하게 바꿔나가야 한다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (177, '彼女の話し方には、相手を安心させる何かがある。', 'かのじょのはなしかたには、あいてをあんしんさせるなにかがある。', '그녀의 말투에는 상대를 안심시키는 무언가가 있다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (178, '経済的な理由もあってか、結婚を先延ばしにする人が増えている。', 'けいざいてきなりゆうもあってか、けっこんをさきのばしにするひとがふえている。', '경제적인 이유도 있어서인지 결혼을 미루는 사람이 늘고 있다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (179, 'あの提案には、いくつか検討すべき点が残されている。', 'あのていあんには、いくつかけんとうすべきてんがのこされている。', '그 제안에는 몇 가지 검토해야 할 점이 남아 있다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (180, '一方的な意見だけで物事を決めるのは危険だ。', 'いっぽうてきないけんだけでものごとをきめるのはきけんだ。', '일방적인 의견만으로 일을 결정하는 것은 위험하다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (181, '彼は重圧の中でも冷静さを失わなかった。', 'かれはじゅうあつのなかでもれいせいさをうしなわなかった。', '그는 압박 속에서도 냉정함을 잃지 않았다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (182, '情報が氾濫している今、正しく判断する力が求められる。', 'じょうほうがはんらんしているいま、ただしくはんだんするちからがもとめられる。', '정보가 넘쳐나는 지금 올바르게 판단하는 능력이 요구된다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (183, '表向きは順調に見えても、内情は決して楽ではない。', 'おもてむきはじゅんちょうにみえても、ないじょうはけっしてらくではない。', '겉으로는 순조로워 보여도 내부 사정은 결코 편하지 않다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (184, '些細なことにこだわりすぎると、本質を見失いかねない。', 'ささいなことにこだわりすぎると、ほんしつをみうしないかねない。', '사소한 것에 지나치게 집착하면 본질을 놓칠 수 있다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (185, '彼の実力を疑う者は、もはや誰もいないだろう。', 'かれのじつりょくをうたがうものは、もはやだれもいないだろう。', '그의 실력을 의심하는 사람은 이제 아무도 없을 것이다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (186, '努力の過程こそが、結果以上に価値があると思う。', 'どりょくのかていこそが、けっかいじょうにかちがあるとおもう。', '노력의 과정이야말로 결과 이상으로 가치가 있다고 생각한다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (187, 'あの発言をきっかけに、社内の雰囲気が一気に変わった。', 'あのはつげんをきっかけに、しゃないのふんいきがいっきにかわった。', '그 발언을 계기로 사내 분위기가 한꺼번에 바뀌었다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (188, '表面上は冷静に見えても、内心は穏やかではなかった。', 'ひょうめんじょうはれいせいにみえても、ないしんはおだやかではなかった。', '표면적으로는 냉정해 보여도 속마음은 평온하지 않았다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (189, '彼女の努力は、周囲の評価とは裏腹に本人には認められていなかった。', 'かのじょのどりょくは、しゅういのひょうかとはうらはらにほんにんにはみとめられていなかった。', '그녀의 노력은 주위의 평가와는 달리 본인에게는 인정받지 못했다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (190, 'これまでの経緯を考えれば、彼の決断もうなずける。', 'これまでのけいいをかんがえれば、かれのけつだんもうなずける。', '지금까지의 경위를 생각하면 그의 결단도 이해가 된다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (191, 'どちらの案にも一長一短があり、決めるのは容易ではない。', 'どちらのあんにもいっちょういったんがあり、きめるのはよういではない。', '어느 쪽 안에도 일장일단이 있어 결정하는 것은 쉽지 않다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (192, '状況を客観的に見ることができれば、判断を誤ることは減る。', 'じょうきょうをきゃっかんてきにみることができれば、はんだんをあやまることはへる。', '상황을 객관적으로 볼 수 있다면 판단을 그르치는 일은 줄어든다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (193, '彼は名前が知られているわりに、実際に会った人は少ない。', 'かれはなまえがしられているわりに、じっさいにあったひとはすくない。', '그는 이름이 알려진 것에 비해 실제로 만난 사람은 적다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (194, '目先の利益にとらわれず、長期的な視点を持つべきだ。', 'めさきのりえきにとらわれず、ちょうきてきなしてんをもつべきだ。', '눈앞의 이익에 얽매이지 않고 장기적인 시각을 가져야 한다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (195, '彼が黙って辞めていったことに、誰もが驚きを隠せなかった。', 'かれがだまってやめていったことに、だれもがおどろきをかくせなかった。', '그가 조용히 그만둔 것에 누구도 놀라움을 감추지 못했다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (196, 'あの一言がなければ、状況はもっと悪化していたに違いない。', 'あのひとことがなければ、じょうきょうはもっとあっかしていたにちがいない。', '그 한마디가 없었다면 상황은 더 악화되었을 것이 틀림없다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (197, '結果だけを見て評価するのは、必ずしも正しいとは言えない。', 'けっかだけをみてひょうかするのは、かならずしもただしいとはいえない。', '결과만 보고 평가하는 것은 반드시 옳다고는 할 수 없다.', 'N2', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (198, '彼の発言は、一見矛盾しているようでいて、実は的を射ている。', 'かれのはつげんは、いっけんむじゅんしているようでいて、じつはまとをいている。', '그의 발언은 겉보기엔 모순된 것 같지만 실은 정확히 핵심을 찌르고 있다.', 'N1', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (199, '経済状況の悪化は、もはや一企業の努力だけでは食い止められない。', 'けいざいじょうきょうのあっかは、もはやいちきぎょうのどりょくだけではくいとめられない。', '경제 상황의 악화는 이제 한 기업의 노력만으로는 막을 수 없다.', 'N1', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (200, '彼女の功績は、後世においても高く評価されるに違いない。', 'かのじょのこうせきは、こうせいにおいてもたかくひょうかされるにちがいない。', '그녀의 공적은 후세에도 높이 평가받을 것이 틀림없다.', 'N1', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (201, 'あらゆる可能性を検討した上で、最終的な判断を下すべきだ。', 'あらゆるかのうせいをけんとうしたうえで、さいしゅうてきなはんだんをくだすべきだ。', '모든 가능성을 검토한 후에 최종적인 판단을 내려야 한다.', 'N1', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (202, '彼の主張には一理あるが、全面的に賛成するには至らない。', 'かれのしゅちょうにはいちりあるが、ぜんめんてきにさんせいするにはいたらない。', '그의 주장에는 일리가 있지만 전면적으로 찬성하기에는 이르지 않는다.', 'N1', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (203, '事態がここまで深刻化するとは、誰も予想し得なかった。', 'じたいがここまでしんこくかするとは、だれもよそうしえなかった。', '사태가 이렇게까지 심각해질 것이라고는 아무도 예상하지 못했다.', 'N1', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (204, 'いかに優秀な人材であろうと、組織の理念に反するなら評価されない。', 'いかにゆうしゅうなじんざいであろうと、そしきのりねんにはんするならひょうかされない。', '아무리 우수한 인재라도 조직의 이념에 반한다면 평가받지 못한다.', 'N1', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (205, '彼の功績を抜きにして、この計画の成功を語ることはできない。', 'かれのこうせきをぬきにして、このけいかくのせいこうをかたることはできない。', '그의 공적을 제외하고는 이 계획의 성공을 말할 수 없다.', 'N1', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (206, '表面的な変化に一喜一憂せず、長期的な視野を持つことが求められる。', 'ひょうめんてきなへんかにいっきいちゆうせず、ちょうきてきなしやをもつことがもとめられる。', '표면적인 변화에 일희일비하지 않고 장기적인 시야를 갖는 것이 요구된다.', 'N1', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (207, '彼の態度からは、後悔の念が微塵も感じられなかった。', 'かれのたいどからは、こうかいのねんがみじんもかんじられなかった。', '그의 태도에서는 후회의 감정이 조금도 느껴지지 않았다.', 'N1', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (208, 'この問題を放置しておけば、いずれ取り返しのつかない事態になりかねない。', 'このもんだいをほうちしておけば、いずれとりかえしのつかないじたいになりかねない。', '이 문제를 방치해두면 결국 돌이킬 수 없는 상황이 될 수도 있다.', 'N1', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (209, '彼女の判断力は、経験によって培われたものに他ならない。', 'かのじょのはんだんりょくは、けいけんによってつちかわれたものにほかならない。', '그녀의 판단력은 경험을 통해 길러진 것에 다름없다.', 'N1', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (210, '一部の反対はあったものの、計画は概ね支持されている。', 'いちぶのはんたいはあったものの、けいかくはおおむねしじされている。', '일부 반대는 있었지만 계획은 대체로 지지받고 있다.', 'N1', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (211, '彼らの努力なくして、この成果はあり得なかったと言える。', 'かれらのどりょくなくして、このせいかはありえなかったといえる。', '그들의 노력 없이는 이 성과는 있을 수 없었다고 할 수 있다.', 'N1', NOW());
INSERT IGNORE INTO dictation_sentences (id, sentence_jp, sentence_reading, sentence_meaning, level, created_at) VALUES (212, '状況の複雑さを鑑みれば、即断は避けるべきだろう。', 'じょうきょうのふくざつさをかんがみれば、そくだんはさけるべきだろう。', '상황의 복잡함을 고려하면 즉단은 피해야 할 것이다.', 'N1', NOW());
